import crypto from 'crypto'

type AppleKey = {
  teamId: string
  keyId: string
  clientId: string
  privateKey: string
}

const MAX_AGE_SECONDS = 60 * 60 * 24 * 150 // Apple accepts at most ~6 months

const base64url = (value: object) => Buffer.from(JSON.stringify(value)).toString('base64url')

/**
 * Sign in with Apple wants a short-lived ES256 JWT as the client secret instead of a static string.
 * Signs one from the .p8 key and caches it, so it never needs to be regenerated by hand.
 */
const createAppleClientSecret = ({ teamId, keyId, clientId, privateKey }: AppleKey) => {
  let cached = { secret: '', expiresAt: 0 }

  return () => {
    const now = Math.floor(Date.now() / 1000)

    // renew well before it expires
    if (cached.secret && cached.expiresAt - now > 60 * 60 * 24 * 7) {
      return cached.secret
    }

    const expiresAt = now + MAX_AGE_SECONDS
    const header = base64url({ alg: 'ES256', kid: keyId })
    const payload = base64url({
      iss: teamId,
      iat: now,
      exp: expiresAt,
      aud: 'https://appleid.apple.com',
      sub: clientId,
    })
    const signature = crypto
      .createSign('sha256')
      .update(`${header}.${payload}`)
      .sign({
        // env vars usually carry the .p8 key with escaped newlines
        key: privateKey.replace(/\\n/g, '\n'),
        dsaEncoding: 'ieee-p1363',
      })
      .toString('base64url')

    cached = { secret: `${header}.${payload}.${signature}`, expiresAt }
    return cached.secret
  }
}

export default createAppleClientSecret
